    fn transfer_to(&mut self) -> Self
        no_unwind
    ;
}

#[verus_verify]
pub trait SpinGuardian {
    type Guard: GuardTransfer;
    type ReadGuard: GuardTransfer;

    fn guard() -> Self::Guard;
    fn read_guard() -> Self::ReadGuard;
}

